function teach(state) {
  if (!state) return 'NOOP';
  // 1. Game over -> JUMP restarts
  if (state.over === true) return 'JUMP';
  var p = state.player || {};
  // 2. First 150 ms after take-off -> keep JUMP held (an early release cuts the jump into a low hop)
