  // 3. Rest of the jump -> let go so the next jump is a fresh press
  if (p.phase === 'coasting') return 'NOOP';
  var t = state.threat;
  // 4. No threat -> NOOP
  if (t === null || t === undefined) return 'NOOP';
  // 5. Duckable bird about to reach the dino (or passing over it) -> DUCK
  if (t.duckable === true && t.near === true) return 'DUCK';
  // 6. Jump now (or as soon as possible) unless the key must be let go first
  if (t.jumpTiming === 'ok' || t.jumpTiming === 'late') return state.jumpReady === false ? 'NOOP' : 'JUMP';
  // 7. Early / n/a -> wait
  return 'NOOP';
}
